CREATE DATABASE IF NOT EXISTS ats_db;
USE ats_db;

-- Create ApplicantProfile table
CREATE TABLE IF NOT EXISTS ApplicantProfile (
    applicant_id INT AUTO_INCREMENT PRIMARY KEY,
    first_name VARCHAR(255) DEFAULT NULL,
    last_name VARCHAR(255) DEFAULT NULL,
    date_of_birth VARCHAR(255) DEFAULT NULL,
    address TEXT DEFAULT NULL,
    phone_number VARCHAR(255) DEFAULT NULL,
    is_encrypted BOOLEAN DEFAULT FALSE
);

-- Create ApplicationDetail table
CREATE TABLE IF NOT EXISTS ApplicationDetail (
    detail_id INT AUTO_INCREMENT PRIMARY KEY,
    applicant_id INT NOT NULL,
    application_role VARCHAR(255) DEFAULT NULL,
    cv_path TEXT,
    cv_raw_text LONGTEXT,
    summary_section TEXT,
    skills_section TEXT,
    experience_section TEXT,
    education_section TEXT,
    accomplishments_section TEXT,
    is_encrypted BOOLEAN DEFAULT FALSE,
    FOREIGN KEY (applicant_id) REFERENCES ApplicantProfile(applicant_id)
);

